/// Look one up by exact name. `None` for a builtin the chapters do not
/// document yet -- callers should fall back to what they printed before
/// rather than claim the name does not exist.
pub fn builtin_doc(name: &str) -> Option<&'static BuiltinDoc> {
    BUILTIN_DOCS
        .binary_search_by(|d| d.name.cmp(name))
        .ok()
        .map(|i| &BUILTIN_DOCS[i])
}
